contracts-lending/governance/GovernanceH.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "./IGovernanceHub.sol";

contract GovernanceHub is AccessControl, ReentrancyGuard, IGovernanceHub {
    bytes32 public constant RISK_COMMITTEE_ROLE = keccak256("RISK_COMMITTEE_ROLE");
    bytes32 public constant SETTLEMENT_AUTHORITY_ROLE = keccak256("SETTLEMENT_AUTHORITY_ROLE");
    bytes32 public constant GUARDIAN_ROLE = keccak256("GUARDIAN_ROLE");

    uint256 public constant MIN_DELAY_FLOOR = 1 hours;
    uint256 public constant MAX_DELAY_CAP = 30 days;
    uint256 public constant DEFAULT_DELAY = 24 hours;
    uint256 public constant DEFAULT_GRACE_PERIOD = 14 days;

    bool public override lendingPaused;
    uint256 public override minimumDelay;
    uint256 public override gracePeriod;
    uint256 public actionNonce;

    mapping(bytes32 => QueuedAction) private _actions;
    bytes32[] private _pendingActionIds;
    mapping(bytes32 => uint256) private _pendingIndex;

    address[] public authorizedTargets;
    mapping(address => bool) public isAuthorizedTarget;

    event TargetAuthorized(address indexed target);
    event TargetRevoked(address indexed target);

    constructor(address admin) {
        require(admin != address(0), "GovernanceHub: zero admin");

        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(RISK_COMMITTEE_ROLE, admin);
        _grantRole(SETTLEMENT_AUTHORITY_ROLE, admin);
        _grantRole(GUARDIAN_ROLE, admin);

        minimumDelay = DEFAULT_DELAY;
        gracePeriod = DEFAULT_GRACE_PERIOD;
        lendingPaused = false;
    }

    function proposeAction(
        ActionType actionType,
        address target,
        bytes calldata callData,
        uint256 eta
    ) external override nonReentrant returns (bytes32 actionId) {
        require(isAuthorizedTarget[target], "GovernanceHub: unauthorized target");
        require(eta >= block.timestamp + minimumDelay, "GovernanceHub: eta too soon");
        require(eta <= block.timestamp + MAX_DELAY_CAP, "GovernanceHub: eta too far");

        _checkRoleForAction(actionType);

        actionId = keccak256(abi.encode(
            actionType,
            target,
            callData,
            eta,
            msg.sender,
            actionNonce++
        ));

        require(_actions[actionId].proposedAt == 0, "GovernanceHub: duplicate action");

        _actions[actionId] = QueuedAction({
            actionId: actionId,
            actionType: actionType,
            target: target,
            callData: callData,
            eta: eta,
            proposer: msg.sender,
            state: ActionState.Pending,
            proposedAt: block.timestamp
        });

        _pendingActionIds.push(actionId);
        _pendingIndex[actionId] = _pendingActionIds.length - 1;

        emit ActionProposed(actionId, actionType, target, callData, eta, msg.sender);
    }

    function cancelAction(bytes32 actionId) external override nonReentrant {
        QueuedAction storage action = _actions[actionId];
        require(action.proposedAt != 0, "GovernanceHub: action not found");
        require(
            action.state == ActionState.Pending || action.state == ActionState.Ready,
            "GovernanceHub: cannot cancel"
        );

        bool canCancel = hasRole(DEFAULT_ADMIN_ROLE, msg.sender) ||
                         hasRole(GUARDIAN_ROLE, msg.sender) ||
                         action.proposer == msg.sender;
        require(canCancel, "GovernanceHub: not authorized to cancel");

        action.state = ActionState.Cancelled;
        _removeFromPending(actionId);

        emit ActionCancelled(actionId, msg.sender);
    }

    function executeAction(bytes32 actionId) external override nonReentrant returns (bool success, bytes memory result) {
        QueuedAction storage action = _actions[actionId];
        require(action.proposedAt != 0, "GovernanceHub: action not found");
        require(
            action.state == ActionState.Pending || action.state == ActionState.Ready,
            "GovernanceHub: not executable"
        );
        require(block.timestamp >= action.eta, "GovernanceHub: eta not reached");
        require(block.timestamp <= action.eta + gracePeriod, "GovernanceHub: action expired");

        _checkRoleForAction(action.actionType);

        action.state = ActionState.Executed;
        _removeFromPending(actionId);

        (success, result) = action.target.call(action.callData);

        emit ActionExecuted(actionId, action.actionType, action.target, msg.sender, success);
    }

    function pauseLending() external override {
        require(hasRole(GUARDIAN_ROLE, msg.sender), "GovernanceHub: not guardian");
        require(!lendingPaused, "GovernanceHub: already paused");

        lendingPaused = true;
        emit LendingPaused(msg.sender);
    }

    function unpauseLending() external override {
        require(
            hasRole(DEFAULT_ADMIN_ROLE, msg.sender) ||
            hasRole(SETTLEMENT_AUTHORITY_ROLE, msg.sender),
            "GovernanceHub: not authorized"
        );
        require(lendingPaused, "GovernanceHub: not paused");

        lendingPaused = false;
        emit LendingUnpaused(msg.sender);
    }

    function setMinimumDelay(uint256 newDelay) external {
        require(hasRole(DEFAULT_ADMIN_ROLE, msg.sender), "GovernanceHub: not admin");
        require(newDelay >= MIN_DELAY_FLOOR, "GovernanceHub: delay too short");
        require(newDelay <= MAX_DELAY_CAP, "GovernanceHub: delay too long");

        uint256 oldDelay = minimumDelay;
        minimumDelay = newDelay;
        emit MinimumDelayUpdated(oldDelay, newDelay);
    }

    function setGracePeriod(uint256 newPeriod) external {
        require(hasRole(DEFAULT_ADMIN_ROLE, msg.sender), "GovernanceHub: not admin");
        require(newPeriod >= 1 days, "GovernanceHub: grace too short");
        require(newPeriod <= 30 days, "GovernanceHub: grace too long");

        uint256 oldPeriod = gracePeriod;
        gracePeriod = newPeriod;
        emit GracePeriodUpdated(oldPeriod, newPeriod);
    }

    function authorizeTarget(address target) external {
        require(hasRole(DEFAULT_ADMIN_ROLE, msg.sender), "GovernanceHub: not admin");
        require(target != address(0), "GovernanceHub: zero address");
        require(!isAuthorizedTarget[target], "GovernanceHub: already authorized");

        isAuthorizedTarget[target] = true;
        authorizedTargets.push(target);
        emit TargetAuthorized(target);
    }

    function revokeTarget(address target) external {
        require(hasRole(DEFAULT_ADMIN_ROLE, msg.sender), "GovernanceHub: not admin");
        require(isAuthorizedTarget[target], "GovernanceHub: not authorized");

        isAuthorizedTarget[target] = false;
        for (uint256 i = 0; i < authorizedTargets.length; i++) {
            if (authorizedTargets[i] == target) {
                authorizedTargets[i] = authorizedTargets[authorizedTargets.length - 1];
                authorizedTargets.pop();
                break;
            }
        }
        emit TargetRevoked(target);
    }

    function getAction(bytes32 actionId) external view override returns (QueuedAction memory) {
        return _actions[actionId];
    }

    function getActionState(bytes32 actionId) external view override returns (ActionState) {
        QueuedAction storage action = _actions[actionId];
        if (action.proposedAt == 0) {
            return ActionState.Pending;
        }
        if (action.state == ActionState.Executed || action.state == ActionState.Cancelled) {
            return action.state;
        }
        if (block.timestamp > action.eta + gracePeriod) {
            return ActionState.Expired;
        }
        if (block.timestamp >= action.eta) {
            return ActionState.Ready;
        }
        return ActionState.Pending;
    }

    function getPendingActions() external view override returns (bytes32[] memory) {
        return _pendingActionIds;
    }

    function getAuthorizedTargets() external view returns (address[] memory) {
        return authorizedTargets;
    }

    function getPendingActionsCount() external view returns (uint256) {
        return _pendingActionIds.length;
    }

    function computeActionId(
        ActionType actionType,
        address target,
        bytes calldata callData,
        uint256 eta,
        address proposer,
        uint256 nonce
    ) external pure returns (bytes32) {
        return keccak256(abi.encode(actionType, target, callData, eta, proposer, nonce));
    }

    function _checkRoleForAction(ActionType actionType) internal view {
        if (actionType == ActionType.RISK_PARAM_UPDATE) {
            require(
                hasRole(RISK_COMMITTEE_ROLE, msg.sender),
                "GovernanceHub: not risk committee"
            );
        } else if (
            actionType == ActionType.PRODUCT_ACTIVATION ||
            actionType == ActionType.PRODUCT_DEACTIVATION ||
            actionType == ActionType.PRODUCT_REGISTRATION ||
            actionType == ActionType.PRODUCT_DEREGISTRATION ||
            actionType == ActionType.MANAGER_UPDATE
        ) {
            require(
                hasRole(SETTLEMENT_AUTHORITY_ROLE, msg.sender),
                "GovernanceHub: not settlement authority"
            );
        } else if (actionType == ActionType.CONTRACT_CONFIG_UPDATE) {
            require(
                hasRole(DEFAULT_ADMIN_ROLE, msg.sender),
                "GovernanceHub: not admin"
            );
        } else if (actionType == ActionType.EMERGENCY_UNPAUSE) {
            require(
                hasRole(DEFAULT_ADMIN_ROLE, msg.sender) ||
                hasRole(SETTLEMENT_AUTHORITY_ROLE, msg.sender),
                "GovernanceHub: not authorized for unpause"
            );
        } else {
            revert("GovernanceHub: unknown action type");
        }
    }

    function _removeFromPending(bytes32 actionId) internal {
        uint256 index = _pendingIndex[actionId];
        uint256 lastIndex = _pendingActionIds.length - 1;

        if (index != lastIndex) {
            bytes32 lastActionId = _pendingActionIds[lastIndex];
            _pendingActionIds[index] = lastActionId;
            _pendingIndex[lastActionId] = index;
        }

        _pendingActionIds.pop();
        delete _pendingIndex[actionId];
    }
}

contracts-lending/governance/IGovernance.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

interface IGovernanceHub {
    enum ActionType {
        RISK_PARAM_UPDATE,
        PRODUCT_ACTIVATION,
        PRODUCT_DEACTIVATION,
        PRODUCT_REGISTRATION,
        PRODUCT_DEREGISTRATION,
        MANAGER_UPDATE,
        CONTRACT_CONFIG_UPDATE,
        EMERGENCY_UNPAUSE
    }

    enum ActionState {
        Pending,
        Ready,
        Executed,
        Cancelled,
        Expired
    }

    struct QueuedAction {
        bytes32 actionId;
        ActionType actionType;
        address target;
        bytes callData;
        uint256 eta;
        address proposer;
        ActionState state;
        uint256 proposedAt;
    }

    function lendingPaused() external view returns (bool);
    function minimumDelay() external view returns (uint256);
    function gracePeriod() external view returns (uint256);

    function proposeAction(
        ActionType actionType,
        address target,
        bytes calldata callData,
        uint256 eta
    ) external returns (bytes32 actionId);

    function cancelAction(bytes32 actionId) external;
    function executeAction(bytes32 actionId) external returns (bool success, bytes memory result);

    function pauseLending() external;
    function unpauseLending() external;

    function getAction(bytes32 actionId) external view returns (QueuedAction memory);
    function getActionState(bytes32 actionId) external view returns (ActionState);
    function getPendingActions() external view returns (bytes32[] memory);

    event ActionProposed(
        bytes32 indexed actionId,
        ActionType indexed actionType,
        address indexed target,
        bytes callData,
        uint256 eta,
        address proposer
    );

    event ActionCancelled(bytes32 indexed actionId, address indexed canceller);

    event ActionExecuted(
        bytes32 indexed actionId,
        ActionType indexed actionType,
        address indexed target,
        address executor,
        bool success
    );

    event LendingPaused(address indexed guardian);
    event LendingUnpaused(address indexed authority);

    event MinimumDelayUpdated(uint256 oldDelay, uint256 newDelay);
    event GracePeriodUpdated(uint256 oldPeriod, uint256 newPeriod);
}

contracts-lending/realestate/dscr/DSCRLo.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "./IDSCRInterfaces.sol";
import "../Interfaces.sol";
import "../../governance/IGovernanceHub.sol";

contract DSCRLoanManager is AccessControl, Pausable, ReentrancyGuard, IDSCRLoanManager {
    using SafeERC20 for IERC20;

    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant UNDERWRITER_ROLE = keccak256("UNDERWRITER_ROLE");
    bytes32 public constant SERVICER_ROLE = keccak256("SERVICER_ROLE");
    bytes32 public constant GUARDIAN_ROLE = keccak256("GUARDIAN_ROLE");
    bytes32 public constant GOVERNANCE_HUB_ROLE = keccak256("GOVERNANCE_HUB_ROLE");

    uint256 public constant BASIS_POINTS = 10000;
    uint256 public constant MONTHS_PER_YEAR = 12;
    uint256 public constant PRECISION = 1e18;

    IERC20 public immutable axusd;
    IDSCRPoolVault public dscrVault;
    IDSCRLoanReceipt public loanReceipt;
    IDSCRRiskConfig public riskConfig;
    IRepaymentRouter public repaymentRouter;

    IPoolVault public fixFlipVault;
    ILoanReceipt public fixFlipLoanReceipt;

    IGovernanceHub public governanceHub;
    bool public governanceEnforced;

    bool public active;
    bool public cashOutEnabled;
    uint256 public maxCashOutBps;

    uint256 public totalOriginated;
    uint256 public totalRepaid;
    uint256 public activeLoans;
    uint256 public totalInterestCollected;

    mapping(address => uint256) public borrowerExposure;

    event ManagerActivated();
    event ManagerDeactivated();
    event CashOutSettingsUpdated(bool enabled, uint256 maxBps);
    event GovernanceHubUpdated(address indexed oldHub, address indexed newHub);
    event GovernanceEnforcementUpdated(bool enforced);

    constructor(
        address _axusd,
        address _dscrVault,
        address _loanReceipt,
        address _riskConfig,
        address _repaymentRouter
    ) {
        require(_axusd != address(0), "DSCRLoanManager: invalid axusd");
        require(_dscrVault != address(0), "DSCRLoanManager: invalid vault");
        require(_loanReceipt != address(0), "DSCRLoanManager: invalid loanReceipt");
        require(_riskConfig != address(0), "DSCRLoanManager: invalid riskConfig");
        require(_repaymentRouter != address(0), "DSCRLoanManager: invalid router");

        axusd = IERC20(_axusd);
        dscrVault = IDSCRPoolVault(_dscrVault);
        loanReceipt = IDSCRLoanReceipt(_loanReceipt);
        riskConfig = IDSCRRiskConfig(_riskConfig);
        repaymentRouter = IRepaymentRouter(_repaymentRouter);

        active = true;
        cashOutEnabled = false;
        maxCashOutBps = 0;
        governanceEnforced = false;

        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ADMIN_ROLE, msg.sender);
        _grantRole(UNDERWRITER_ROLE, msg.sender);
        _grantRole(SERVICER_ROLE, msg.sender);
        _grantRole(GUARDIAN_ROLE, msg.sender);
    }

    modifier whenNotGovernancePaused() {
        if (governanceEnforced && address(governanceHub) != address(0)) {
            require(!governanceHub.lendingPaused(), "DSCRLoanManager: governance paused");
        }
        _;
    }

    modifier onlyAdminAuthority() {
        bool authorized = hasRole(ADMIN_ROLE, msg.sender) ||
                          hasRole(GOVERNANCE_HUB_ROLE, msg.sender);
        require(authorized, "DSCRLoanManager: not authorized");
        _;
    }

    function setGovernanceHub(address _governanceHub) external onlyRole(DEFAULT_ADMIN_ROLE) {
        address oldHub = address(governanceHub);
        governanceHub = IGovernanceHub(_governanceHub);

        if (oldHub != address(0)) {
            _revokeRole(GOVERNANCE_HUB_ROLE, oldHub);
        }
        if (_governanceHub != address(0)) {
            _grantRole(GOVERNANCE_HUB_ROLE, _governanceHub);
        }

        emit GovernanceHubUpdated(oldHub, _governanceHub);
    }

    function setGovernanceEnforced(bool _enforced) external onlyRole(DEFAULT_ADMIN_ROLE) {
        governanceEnforced = _enforced;
        emit GovernanceEnforcementUpdated(_enforced);
    }

    function originate(
        OriginateParams calldata params
    ) external override onlyRole(UNDERWRITER_ROLE) nonReentrant whenNotPaused whenNotGovernancePaused returns (uint256) {
        require(active, "DSCRLoanManager: not active");
        require(params.borrower != address(0), "DSCRLoanManager: invalid borrower");
        require(params.principal > 0, "DSCRLoanManager: zero principal");

        IDSCRRiskConfig.DSCRProductRisk memory risk = riskConfig.getDSCRProductRisk(params.productId);
        require(risk.active, "DSCRLoanManager: product not active");

        require(params.principal >= risk.minLoanSize, "DSCRLoanManager: below min loan size");
        require(params.principal <= risk.maxLoanSize, "DSCRLoanManager: exceeds max loan size");

        uint256 newExposure = borrowerExposure[params.borrower] + params.principal;
        require(newExposure <= risk.maxBorrowerExposure, "DSCRLoanManager: exceeds borrower exposure limit");

        uint256 ltvBps = (params.principal * BASIS_POINTS) / params.appraisedValue;
        require(ltvBps <= risk.maxLtvBps, "DSCRLoanManager: exceeds max LTV");

        uint256 monthlyPayment = computeMonthlyPayment(params.principal, risk.interestRateBps, risk.termMonths);

        uint256 netRent = params.monthlyRent > params.monthlyExpenses 
            ? params.monthlyRent - params.monthlyExpenses 
            : 0;
        uint256 dscrBps = (netRent * BASIS_POINTS) / monthlyPayment;
        require(dscrBps >= risk.minDscrBps, "DSCRLoanManager: DSCR too low");

        require(
            dscrVault.availableLiquidity() >= params.principal,
            "DSCRLoanManager: insufficient vault liquidity"
        );

        uint256 loanId = loanReceipt.mintDSCRLoan(
            params.borrower,
            params.productId,
            params.principal,
            params.appraisedValue,
            params.monthlyRent,
            monthlyPayment,
            risk.interestRateBps,
            risk.termMonths,
            dscrBps,
            ltvBps,
            params.collateralHash
        );

        dscrVault.lockForLoan(params.principal);
        dscrVault.disburse(params.borrower, params.principal);

        totalOriginated += params.principal;
        activeLoans++;
        borrowerExposure[params.borrower] = newExposure;

        emit DSCRLoanFunded(
            loanId,
            params.borrower,
            params.principal,
            params.productId,
            dscrBps,
            ltvBps
        );

        return loanId;
    }

    function payOnChain(uint256 loanId, uint256 amount) external override nonReentrant whenNotPaused {
        require(amount > 0, "DSCRLoanManager: zero amount");

        (
            uint256 loanId_,
            ,
            address borrower,
            uint256 originalPrincipal,
            uint256 principalOutstanding,
            IDSCRLoanReceipt.DSCRLoanStatus status
        ) = loanReceipt.getDSCRLoanCore(loanId);
        require(loanId_ == loanId, "DSCRLoanManager: loan not found");
        require(
            status == IDSCRLoanReceipt.DSCRLoanStatus.Active ||
            status == IDSCRLoanReceipt.DSCRLoanStatus.Current ||
            status == IDSCRLoanReceipt.DSCRLoanStatus.Delinquent30 ||
            status == IDSCRLoanReceipt.DSCRLoanStatus.Delinquent60 ||
            status == IDSCRLoanReceipt.DSCRLoanStatus.Delinquent90,
            "DSCRLoanManager: loan not payable"
        );

        (
            uint256 interestRateBps,
            uint256 monthlyPayment,
            ,
            ,
            ,
        ) = loanReceipt.getDSCRLoanTerms(loanId);

        (uint256 principalPortion, uint256 interestPortion) = _computePaymentSplitSimple(
            principalOutstanding,
            interestRateBps,
            monthlyPayment,
            amount
        );

        axusd.safeTransferFrom(msg.sender, address(repaymentRouter), amount);
        repaymentRouter.routePayment(loanId, amount, principalPortion, interestPortion);

        loanReceipt.recordDSCRPayment(loanId, principalPortion, interestPortion);

        totalRepaid += principalPortion;
        totalInterestCollected += interestPortion;

        if (principalOutstanding <= principalPortion) {
            activeLoans--;
            borrowerExposure[borrower] -= originalPrincipal;
            dscrVault.unlockFromLoan(originalPrincipal);
        }

        emit PaymentReceived(loanId, amount, principalPortion, interestPortion, true);
    }

    function postOffChainPayment(
        uint256 loanId, 
        uint256 amount, 
        bytes32 referenceHash
    ) external override onlyRole(SERVICER_ROLE) nonReentrant whenNotPaused {
        require(amount > 0, "DSCRLoanManager: zero amount");
        require(referenceHash != bytes32(0), "DSCRLoanManager: invalid reference");

        (
            uint256 loanId_,
            ,
            address borrower,
            uint256 originalPrincipal,
            uint256 principalOutstanding,
            IDSCRLoanReceipt.DSCRLoanStatus status
        ) = loanReceipt.getDSCRLoanCore(loanId);
        require(loanId_ == loanId, "DSCRLoanManager: loan not found");
        require(
            status == IDSCRLoanReceipt.DSCRLoanStatus.Active ||
            status == IDSCRLoanReceipt.DSCRLoanStatus.Current ||
            status == IDSCRLoanReceipt.DSCRLoanStatus.Delinquent30 ||
            status == IDSCRLoanReceipt.DSCRLoanStatus.Delinquent60 ||
            status == IDSCRLoanReceipt.DSCRLoanStatus.Delinquent90,
            "DSCRLoanManager: loan not payable"
        );

        (
            uint256 interestRateBps,
            uint256 monthlyPayment,
            ,
            ,
            ,
        ) = loanReceipt.getDSCRLoanTerms(loanId);

        (uint256 principalPortion, uint256 interestPortion) = _computePaymentSplitSimple(
            principalOutstanding,
            interestRateBps,
            monthlyPayment,
            amount
        );

        loanReceipt.recordDSCRPayment(loanId, principalPortion, interestPortion);

        totalRepaid += principalPortion;
        totalInterestCollected += interestPortion;

        if (principalOutstanding <= principalPortion) {
            activeLoans--;
            borrowerExposure[borrower] -= originalPrincipal;
            dscrVault.unlockFromLoan(originalPrincipal);
        }

        dscrVault.reportYield(interestPortion);

        emit PaymentPosted(loanId, amount, referenceHash, msg.sender);
        emit PaymentReceived(loanId, amount, principalPortion, interestPortion, false);
    }

    function refinanceFromFixFlip(
        uint256 fixFlipLoanId,
        uint256 newProductId,
        uint256 newPrincipal,
        uint256 appraisedValue,
        uint256 monthlyRent,
        uint256 monthlyExpenses,
        bytes32 collateralHash
    ) external override onlyRole(UNDERWRITER_ROLE) nonReentrant whenNotPaused whenNotGovernancePaused returns (uint256) {
        require(active, "DSCRLoanManager: not active");
        require(address(fixFlipLoanReceipt) != address(0), "DSCRLoanManager: fixflip not configured");
        require(address(fixFlipVault) != address(0), "DSCRLoanManager: fixflip vault not configured");

        ILoanReceipt.LoanData memory fixFlipLoan = fixFlipLoanReceipt.getLoan(fixFlipLoanId);
        require(fixFlipLoan.loanId == fixFlipLoanId, "DSCRLoanManager: fixflip loan not found");
        require(
            fixFlipLoan.status == ILoanReceipt.LoanStatus.Active ||
            fixFlipLoan.status == ILoanReceipt.LoanStatus.Repaying,
            "DSCRLoanManager: fixflip loan not eligible"
        );

        uint256 payoffAmount = fixFlipLoan.principal + fixFlipLoanReceipt.calculateInterestDue(fixFlipLoanId) - fixFlipLoan.amountRepaid;

        require(newPrincipal >= payoffAmount, "DSCRLoanManager: insufficient principal for payoff");

        IDSCRRiskConfig.DSCRProductRisk memory risk = riskConfig.getDSCRProductRisk(newProductId);
        require(risk.active, "DSCRLoanManager: product not active");
        require(newPrincipal >= risk.minLoanSize, "DSCRLoanManager: below min loan size");
        require(newPrincipal <= risk.maxLoanSize, "DSCRLoanManager: exceeds max loan size");

        uint256 ltvBps = (newPrincipal * BASIS_POINTS) / appraisedValue;
        require(ltvBps <= risk.maxLtvBps, "DSCRLoanManager: exceeds max LTV");

        uint256 monthlyPayment = computeMonthlyPayment(newPrincipal, risk.interestRateBps, risk.termMonths);
        uint256 netRent = monthlyRent > monthlyExpenses ? monthlyRent - monthlyExpenses : 0;
        uint256 dscrBps = (netRent * BASIS_POINTS) / monthlyPayment;
        require(dscrBps >= risk.minDscrBps, "DSCRLoanManager: DSCR too low");

        uint256 cashOut = newPrincipal - payoffAmount;
        if (!cashOutEnabled) {
            require(cashOut == 0, "DSCRLoanManager: cash-out disabled");
        } else if (maxCashOutBps > 0) {
            uint256 maxCashOut = (appraisedValue * maxCashOutBps) / BASIS_POINTS;
            require(cashOut <= maxCashOut, "DSCRLoanManager: cash-out exceeds limit");
        }

        require(
            dscrVault.availableLiquidity() >= newPrincipal,
            "DSCRLoanManager: insufficient vault liquidity"
        );

        dscrVault.lockForLoan(newPrincipal);

        dscrVault.disburse(address(fixFlipVault), payoffAmount);
        fixFlipVault.unlockFromLoan(fixFlipLoan.principal);

        if (cashOut > 0) {
            dscrVault.disburse(fixFlipLoan.borrower, cashOut);
        }

        uint256 newLoanId = loanReceipt.mintDSCRLoan(
            fixFlipLoan.borrower,
            newProductId,
            newPrincipal,
            appraisedValue,
            monthlyRent,
            monthlyPayment,
            risk.interestRateBps,
            risk.termMonths,
            dscrBps,
            ltvBps,
            collateralHash
        );

        fixFlipLoanReceipt.updateLoanStatus(fixFlipLoanId, ILoanReceipt.LoanStatus.Repaid);

        totalOriginated += newPrincipal;
        activeLoans++;
        borrowerExposure[fixFlipLoan.borrower] += newPrincipal;

        emit RefinanceCompleted(fixFlipLoanId, newLoanId, payoffAmount, cashOut);
        emit DSCRLoanFunded(
            newLoanId,
            fixFlipLoan.borrower,
            newPrincipal,
            newProductId,
            dscrBps,
            ltvBps
        );

        return newLoanId;
    }

    function computeMonthlyPayment(
        uint256 principal, 
        uint256 aprBps, 
        uint256 termMonths
    ) public pure override returns (uint256) {
        if (aprBps == 0) {
            return principal / termMonths;
        }

        uint256 monthlyRateBps = aprBps / MONTHS_PER_YEAR;

        uint256 monthlyRate = (monthlyRateBps * PRECISION) / BASIS_POINTS;

        uint256 onePlusR = PRECISION + monthlyRate;
        uint256 onePlusRPowN = PRECISION;

        for (uint256 i = 0; i < termMonths; i++) {
            onePlusRPowN = (onePlusRPowN * onePlusR) / PRECISION;
        }

        uint256 numerator = (principal * monthlyRate * onePlusRPowN) / PRECISION;
        uint256 denominator = onePlusRPowN - PRECISION;

        if (denominator == 0) {
            return principal / termMonths;
        }

        return numerator / denominator;
    }

    function _computePaymentSplitSimple(
        uint256 principalOutstanding,
        uint256 interestRateBps,
        uint256 monthlyPayment,
        uint256 amount
    ) internal pure returns (uint256 principalPortion, uint256 interestPortion) {
        uint256 monthlyInterest = (principalOutstanding * interestRateBps) / (BASIS_POINTS * MONTHS_PER_YEAR);

        if (amount <= monthlyInterest) {
            interestPortion = amount;
            principalPortion = 0;
        } else {
            interestPortion = monthlyInterest;
            principalPortion = amount - interestPortion;

            if (principalPortion > principalOutstanding) {
                principalPortion = principalOutstanding;
            }
        }
    }

    function markDelinquent(
        uint256 loanId, 
        IDSCRLoanReceipt.DSCRLoanStatus newStatus
    ) external override onlyRole(SERVICER_ROLE) {
        require(
            newStatus == IDSCRLoanReceipt.DSCRLoanStatus.Delinquent30 ||
            newStatus == IDSCRLoanReceipt.DSCRLoanStatus.Delinquent60 ||
            newStatus == IDSCRLoanReceipt.DSCRLoanStatus.Delinquent90,
            "DSCRLoanManager: invalid delinquency status"
        );

        loanReceipt.updateDSCRLoanStatus(loanId, newStatus);
    }

    function markDefault(uint256 loanId) external override onlyAdminAuthority {
        (
            uint256 loanId_,
            ,
            ,
            ,
            uint256 principalOutstanding,
            IDSCRLoanReceipt.DSCRLoanStatus status
        ) = loanReceipt.getDSCRLoanCore(loanId);
        require(loanId_ == loanId, "DSCRLoanManager: loan not found");
        require(
            status == IDSCRLoanReceipt.DSCRLoanStatus.Delinquent90,
            "DSCRLoanManager: must be 90+ days delinquent"
        );

        loanReceipt.updateDSCRLoanStatus(loanId, IDSCRLoanReceipt.DSCRLoanStatus.Default);
        activeLoans--;

        emit LoanDefaulted(loanId, principalOutstanding);
    }

    function setFixFlipContracts(
        address _fixFlipVault,
        address _fixFlipLoanReceipt
    ) external onlyAdminAuthority whenNotGovernancePaused {
        fixFlipVault = IPoolVault(_fixFlipVault);
        fixFlipLoanReceipt = ILoanReceipt(_fixFlipLoanReceipt);
    }

    function setCashOutSettings(bool _enabled, uint256 _maxBps) external onlyAdminAuthority whenNotGovernancePaused {
        require(_maxBps <= 2500, "DSCRLoanManager: max cash-out too high");
        cashOutEnabled = _enabled;
        maxCashOutBps = _maxBps;
        emit CashOutSettingsUpdated(_enabled, _maxBps);
    }

    function getStats() external view returns (
        uint256 _totalOriginated,
        uint256 _totalRepaid,
        uint256 _activeLoans,
        uint256 _availableLiquidity,
        uint256 _totalInterestCollected
    ) {
        return (
            totalOriginated, 
            totalRepaid, 
            activeLoans, 
            dscrVault.availableLiquidity(),
            totalInterestCollected
        );
    }

    function activate() external onlyAdminAuthority whenNotGovernancePaused {
        active = true;
        emit ManagerActivated();
    }

    function deactivate() external onlyAdminAuthority {
        active = false;
        emit ManagerDeactivated();
    }

    function setDSCRVault(address _vault) external onlyAdminAuthority whenNotGovernancePaused {
        require(_vault != address(0), "DSCRLoanManager: invalid vault");
        dscrVault = IDSCRPoolVault(_vault);
    }

    function setLoanReceipt(address _loanReceipt) external onlyAdminAuthority whenNotGovernancePaused {
        require(_loanReceipt != address(0), "DSCRLoanManager: invalid loanReceipt");
        loanReceipt = IDSCRLoanReceipt(_loanReceipt);
    }

    function setRiskConfig(address _riskConfig) external onlyAdminAuthority whenNotGovernancePaused {
        require(_riskConfig != address(0), "DSCRLoanManager: invalid riskConfig");
        riskConfig = IDSCRRiskConfig(_riskConfig);
    }

    function setRepaymentRouter(address _router) external onlyAdminAuthority whenNotGovernancePaused {
        require(_router != address(0), "DSCRLoanManager: invalid router");
        repaymentRouter = IRepaymentRouter(_router);
    }

    function pause() external onlyRole(GUARDIAN_ROLE) {
        _pause();
    }

    function unpause() external onlyAdminAuthority {
        _unpause();
    }
}

