// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "./IDSCRInterfaces.sol";
import "../../governance/IGovernanceHub.sol";

contract DSCRRiskConfig is AccessControl, IDSCRRiskConfig {
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant RISK_MANAGER_ROLE = keccak256("RISK_MANAGER_ROLE");
    bytes32 public constant GOVERNANCE_HUB_ROLE = keccak256("GOVERNANCE_HUB_ROLE");

    uint256 public constant MAX_LTV_CAP = 8000;
    uint256 public constant MIN_DSCR_FLOOR = 10000;
    uint256 public constant BASIS_POINTS = 10000;
    uint256 public constant MAX_TERM_MONTHS = 360;

    mapping(uint256 => DSCRProductRisk) private _productRisks;
    uint256[] public productIds;

    IGovernanceHub public governanceHub;
    bool public governanceEnforced;

    event GovernanceHubUpdated(address indexed oldHub, address indexed newHub);
    event GovernanceEnforcementUpdated(bool enforced);

    constructor() {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ADMIN_ROLE, msg.sender);
        _grantRole(RISK_MANAGER_ROLE, msg.sender);
        governanceEnforced = false;
    }

    modifier whenNotGovernancePaused() {
        if (governanceEnforced && address(governanceHub) != address(0)) {
            require(!governanceHub.lendingPaused(), "DSCRRiskConfig: lending paused");
        }
        _;
    }

    modifier onlyRiskAuthority() {
        bool authorized = hasRole(RISK_MANAGER_ROLE, msg.sender) ||
                          hasRole(GOVERNANCE_HUB_ROLE, msg.sender);
        require(authorized, "DSCRRiskConfig: not authorized");
        _;
    }

    modifier onlyAdminAuthority() {
        bool authorized = hasRole(ADMIN_ROLE, msg.sender) ||
                          hasRole(GOVERNANCE_HUB_ROLE, msg.sender);
        require(authorized, "DSCRRiskConfig: not authorized");
        _;
    }

    function setGovernanceHub(address _governanceHub) external onlyRole(DEFAULT_ADMIN_ROLE) {
        address oldHub = address(governanceHub);
        governanceHub = IGovernanceHub(_governanceHub);

        if (oldHub != address(0)) {
            _revokeRole(GOVERNANCE_HUB_ROLE, oldHub);
        }
        if (_governanceHub != address(0)) {
            _grantRole(GOVERNANCE_HUB_ROLE, _governanceHub);
        }

        emit GovernanceHubUpdated(oldHub, _governanceHub);
    }

    function setGovernanceEnforced(bool _enforced) external onlyRole(DEFAULT_ADMIN_ROLE) {
        governanceEnforced = _enforced;
        emit GovernanceEnforcementUpdated(_enforced);
    }

    function setDSCRProductRisk(
        uint256 productId,
        DSCRProductRisk calldata config
    ) external override onlyRiskAuthority whenNotGovernancePaused {
        require(config.maxLtvBps > 0 && config.maxLtvBps <= MAX_LTV_CAP, "DSCRRiskConfig: invalid LTV");
        require(config.minDscrBps >= MIN_DSCR_FLOOR, "DSCRRiskConfig: DSCR too low");
        require(config.termMonths > 0 && config.termMonths <= MAX_TERM_MONTHS, "DSCRRiskConfig: invalid term");
        require(config.maxLoanSize > config.minLoanSize, "DSCRRiskConfig: invalid loan size range");
        require(config.interestRateBps > 0 && config.interestRateBps <= 2000, "DSCRRiskConfig: invalid interest rate");
        require(config.originationFeeBps <= 500, "DSCRRiskConfig: origination fee too high");
        require(
            config.insuranceReserveBps + config.protocolFeeBps <= BASIS_POINTS,
            "DSCRRiskConfig: fee split exceeds 100%"
        );

        bool isNew = _productRisks[productId].productId == 0;
        _productRisks[productId] = config;
        _productRisks[productId].productId = productId;

        if (isNew) {
            productIds.push(productId);
        }

        emit DSCRProductRiskUpdated(
            productId,
            config.maxLtvBps,
            config.minDscrBps,
            config.interestRateBps,
            config.termMonths
        );
    }

    function getDSCRProductRisk(uint256 productId) external view override returns (DSCRProductRisk memory) {
        require(_productRisks[productId].productId != 0, "DSCRRiskConfig: product not found");
        return _productRisks[productId];
    }

    function isDSCRProductActive(uint256 productId) external view override returns (bool) {
        return _productRisks[productId].active;
    }

    function deactivateProduct(uint256 productId) external onlyAdminAuthority whenNotGovernancePaused {
        require(_productRisks[productId].productId != 0, "DSCRRiskConfig: product not found");
        _productRisks[productId].active = false;
        emit DSCRProductRiskUpdated(productId, 0, 0, 0, 0);
    }

    function activateProduct(uint256 productId) external onlyAdminAuthority whenNotGovernancePaused {
        require(_productRisks[productId].productId != 0, "DSCRRiskConfig: product not found");
        _productRisks[productId].active = true;
        emit DSCRProductRiskUpdated(
            productId,
            _productRisks[productId].maxLtvBps,
            _productRisks[productId].minDscrBps,
            _productRisks[productId].interestRateBps,
            _productRisks[productId].termMonths
        );
    }

    function getProductCount() external view returns (uint256) {
        return productIds.length;
    }

    function getAllProductIds() external view returns (uint256[] memory) {
        return productIds;
    }
}

contracts-lending/realestate/dscr/IDSCRI.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC721/IERC721.sol";
import "../Interfaces.sol";

interface IDSCRPoolVault {
    function deposit(uint256 assets, address receiver) external returns (uint256 shares);
    function withdraw(uint256 assets, address receiver, address owner) external returns (uint256 shares);
    function redeem(uint256 shares, address receiver, address owner) external returns (uint256 assets);
    function lockForLoan(uint256 amount) external;
    function unlockFromLoan(uint256 amount) external;
    function reportYield(uint256 amount) external;
    function disburse(address recipient, uint256 amount) external;
    function totalAssets() external view returns (uint256);
    function availableLiquidity() external view returns (uint256);
    function lockedLiquidity() external view returns (uint256);
    function convertToShares(uint256 assets) external view returns (uint256);
    function convertToAssets(uint256 shares) external view returns (uint256);
}

interface IDSCRRiskConfig {
    struct DSCRProductRisk {
        uint256 productId;
        uint256 maxLtvBps;
        uint256 minDscrBps;
        uint256 interestRateBps;
        uint256 originationFeeBps;
        uint256 termMonths;
        uint256 minLoanSize;
        uint256 maxLoanSize;
        uint256 maxBorrowerExposure;
        uint256 insuranceReserveBps;
        uint256 protocolFeeBps;
        bool active;
    }

    function getDSCRProductRisk(uint256 productId) external view returns (DSCRProductRisk memory);
    function setDSCRProductRisk(uint256 productId, DSCRProductRisk calldata config) external;
    function isDSCRProductActive(uint256 productId) external view returns (bool);

    event DSCRProductRiskUpdated(
        uint256 indexed productId,
        uint256 maxLtvBps,
        uint256 minDscrBps,
        uint256 interestRateBps,
        uint256 termMonths
    );
}

interface IDSCRLoanReceipt is IERC721 {
    enum DSCRLoanStatus { 
        Active, 
        Current, 
        Delinquent30, 
        Delinquent60, 
        Delinquent90, 
        Default, 
        PaidOff, 
        RefinancedOut 
    }

    struct DSCRLoanData {
        uint256 loanId;
        uint256 productId;
        address borrower;
        uint256 originalPrincipal;
        uint256 principalOutstanding;
        uint256 interestRateBps;
        uint256 monthlyPayment;
        uint256 termMonths;
        uint256 paymentsRemaining;
        uint256 startTimestamp;
        uint256 lastPaymentTimestamp;
        uint256 totalInterestPaid;
        uint256 totalPrincipalPaid;
        uint256 appraisedValue;
        uint256 monthlyRent;
        uint256 dscrBps;
        uint256 ltvBps;
        DSCRLoanStatus status;
        bytes32 collateralHash;
    }

    function mintDSCRLoan(
        address borrower,
        uint256 productId,
        uint256 principal,
        uint256 appraisedValue,
        uint256 monthlyRent,
        uint256 monthlyPayment,
        uint256 interestRateBps,
        uint256 termMonths,
        uint256 dscrBps,
        uint256 ltvBps,
        bytes32 collateralHash
    ) external returns (uint256 loanId);

    function recordDSCRPayment(
        uint256 loanId,
        uint256 principalPortion,
        uint256 interestPortion
    ) external;

    function updateDSCRLoanStatus(uint256 loanId, DSCRLoanStatus status) external;
    function getDSCRLoansByBorrower(address borrower) external view returns (uint256[] memory);
    function setRefinancedOut(uint256 loanId, uint256 newLoanId) external;

    function getDSCRLoanCore(uint256 loanId) external view returns (
        uint256 loanId_,
        uint256 productId,
        address borrower,
        uint256 originalPrincipal,
        uint256 principalOutstanding,
        DSCRLoanStatus status
    );

    function getDSCRLoanTerms(uint256 loanId) external view returns (
        uint256 interestRateBps,
        uint256 monthlyPayment,
        uint256 termMonths,
        uint256 paymentsRemaining,
        uint256 dscrBps,
        uint256 ltvBps
    );

    function getDSCRLoanPayments(uint256 loanId) external view returns (
        uint256 startTimestamp,
        uint256 lastPaymentTimestamp,
        uint256 totalInterestPaid,
        uint256 totalPrincipalPaid
    );

    function getDSCRLoanProperty(uint256 loanId) external view returns (
        uint256 appraisedValue,
        uint256 monthlyRent,
        bytes32 collateralHash
    );

    event DSCRLoanOriginated(
        uint256 indexed loanId,
        address indexed borrower,
        uint256 principal,
        uint256 productId,
        uint256 dscrBps,
        uint256 ltvBps,
        uint256 monthlyPayment
    );
    event DSCRLoanPayment(
        uint256 indexed loanId,
        address indexed payer,
        uint256 principalPortion,
        uint256 interestPortion,
        uint256 principalRemaining
    );
    event DSCRLoanStatusChanged(uint256 indexed loanId, DSCRLoanStatus oldStatus, DSCRLoanStatus newStatus);
    event DSCRLoanRefinanced(uint256 indexed oldLoanId, uint256 indexed newLoanId);
}

interface IDSCRLoanManager {
    struct OriginateParams {
        address borrower;
        uint256 productId;
        uint256 principal;
        uint256 appraisedValue;
        uint256 monthlyRent;
        uint256 monthlyExpenses;
        bytes32 collateralHash;
    }

    function originate(OriginateParams calldata params) external returns (uint256 loanId);
    function payOnChain(uint256 loanId, uint256 amount) external;
    function postOffChainPayment(uint256 loanId, uint256 amount, bytes32 referenceHash) external;
    function refinanceFromFixFlip(
        uint256 fixFlipLoanId,
        uint256 newProductId,
        uint256 newPrincipal,
        uint256 appraisedValue,
        uint256 monthlyRent,
        uint256 monthlyExpenses,
        bytes32 collateralHash
    ) external returns (uint256 newLoanId);
    function computeMonthlyPayment(uint256 principal, uint256 aprBps, uint256 termMonths) external pure returns (uint256);
    function markDelinquent(uint256 loanId, IDSCRLoanReceipt.DSCRLoanStatus newStatus) external;
    function markDefault(uint256 loanId) external;

    event DSCRLoanFunded(
        uint256 indexed loanId,
        address indexed borrower,
        uint256 principal,
        uint256 productId,
        uint256 dscrBps,
        uint256 ltvBps
    );
    event PaymentReceived(
        uint256 indexed loanId,
        uint256 amount,
        uint256 principalPortion,
        uint256 interestPortion,
        bool isOnChain
    );
    event PaymentPosted(
        uint256 indexed loanId,
        uint256 amount,
        bytes32 indexed referenceHash,
        address indexed postedBy
    );
    event RefinanceCompleted(
        uint256 indexed oldLoanId,
        uint256 indexed newLoanId,
        uint256 payoffAmount,
        uint256 cashOut
    );
    event LoanDefaulted(uint256 indexed loanId, uint256 outstandingBalance);
}

contracts-lending/realestate/FixFlipMana.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "./Interfaces.sol";
import "../governance/IGovernanceHub.sol";

contract FixFlipManager is AccessControl, Pausable, ReentrancyGuard, IProductManager {
    using SafeERC20 for IERC20;

    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant UNDERWRITER_ROLE = keccak256("UNDERWRITER_ROLE");
    bytes32 public constant GUARDIAN_ROLE = keccak256("GUARDIAN_ROLE");
    bytes32 public constant GOVERNANCE_HUB_ROLE = keccak256("GOVERNANCE_HUB_ROLE");

    uint256 public constant PRODUCT_ID = 1;

    IERC20 public immutable axusd;
    IPoolVault public vault;
    ILoanReceipt public loanReceipt;
    IRiskConfig public riskConfig;
    IRepaymentRouter public repaymentRouter;

    IGovernanceHub public governanceHub;
    bool public governanceEnforced;

    bool public active;
    uint256 public totalOriginated;
    uint256 public totalRepaid;
    uint256 public activeLoans;

    mapping(uint256 => LoanDetails) public loanDetails;

    struct LoanDetails {
        uint256 purchasePrice;
        uint256 afterRepairValue;
        uint256 rehabBudget;
        address approvedBy;
        uint256 approvedAt;
        uint256 fundedAt;
        uint256 closedAt;
    }

    event LoanFunded(
        uint256 indexed loanId,
        address indexed borrower,
        uint256 principal,
        uint256 purchasePrice,
        uint256 arv
    );
    event LoanPaymentReceived(uint256 indexed loanId, uint256 amount, uint256 remaining);
    event LoanFullyRepaid(uint256 indexed loanId, uint256 totalPaid);
    event LoanDefaulted(uint256 indexed loanId);
    event ManagerActivated();
    event ManagerDeactivated();
    event GovernanceHubUpdated(address indexed oldHub, address indexed newHub);
    event GovernanceEnforcementUpdated(bool enforced);

    constructor(
        address _axusd,
        address _vault,
        address _loanReceipt,
        address _riskConfig,
        address _repaymentRouter
    ) {
        require(_axusd != address(0), "FixFlipManager: invalid axusd");
        require(_vault != address(0), "FixFlipManager: invalid vault");
        require(_loanReceipt != address(0), "FixFlipManager: invalid loanReceipt");
        require(_riskConfig != address(0), "FixFlipManager: invalid riskConfig");
        require(_repaymentRouter != address(0), "FixFlipManager: invalid router");

        axusd = IERC20(_axusd);
        vault = IPoolVault(_vault);
        loanReceipt = ILoanReceipt(_loanReceipt);
        riskConfig = IRiskConfig(_riskConfig);
        repaymentRouter = IRepaymentRouter(_repaymentRouter);
        active = true;
        governanceEnforced = false;

        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ADMIN_ROLE, msg.sender);
        _grantRole(UNDERWRITER_ROLE, msg.sender);
        _grantRole(GUARDIAN_ROLE, msg.sender);
    }

    modifier whenNotGovernancePaused() {
        if (governanceEnforced && address(governanceHub) != address(0)) {
            require(!governanceHub.lendingPaused(), "FixFlipManager: governance paused");
        }
        _;
    }

    modifier onlyAdminAuthority() {
        bool authorized = hasRole(ADMIN_ROLE, msg.sender) ||
                          hasRole(GOVERNANCE_HUB_ROLE, msg.sender);
        require(authorized, "FixFlipManager: not authorized");
        _;
    }

    function setGovernanceHub(address _governanceHub) external onlyRole(DEFAULT_ADMIN_ROLE) {
        address oldHub = address(governanceHub);
        governanceHub = IGovernanceHub(_governanceHub);

        if (oldHub != address(0)) {
            _revokeRole(GOVERNANCE_HUB_ROLE, oldHub);
        }
        if (_governanceHub != address(0)) {
            _grantRole(GOVERNANCE_HUB_ROLE, _governanceHub);
        }

        emit GovernanceHubUpdated(oldHub, _governanceHub);
    }

    function setGovernanceEnforced(bool _enforced) external onlyRole(DEFAULT_ADMIN_ROLE) {
        governanceEnforced = _enforced;
        emit GovernanceEnforcementUpdated(_enforced);
    }

    function productId() external pure override returns (uint256) {
        return PRODUCT_ID;
    }

    function isActive() external view override returns (bool) {
        if (governanceEnforced && address(governanceHub) != address(0)) {
            if (governanceHub.lendingPaused()) {
                return false;
            }
        }
        return active && !paused();
    }

    function originate(
        address borrower,
        uint256 principal,
        IUnderwriter.DealTerms calldata terms
    ) external override onlyRole(UNDERWRITER_ROLE) nonReentrant whenNotPaused whenNotGovernancePaused returns (uint256) {
        require(active, "FixFlipManager: not active");
        require(borrower != address(0), "FixFlipManager: invalid borrower");
        require(principal > 0, "FixFlipManager: zero principal");

        IRiskConfig.ProductRisk memory risk = riskConfig.getProductRisk(PRODUCT_ID);
        require(risk.active, "FixFlipManager: product not active");

        require(principal >= risk.minLoanSize, "FixFlipManager: below min loan size");
        require(principal <= risk.maxLoanSize, "FixFlipManager: exceeds max loan size");
        require(terms.termDays <= risk.maxTermDays, "FixFlipManager: term too long");

        uint256 maxLoan = (terms.afterRepairValue * risk.maxLtvBps) / 10000;
        require(principal <= maxLoan, "FixFlipManager: exceeds max LTV");

        require(
            vault.availableLiquidity() >= principal,
            "FixFlipManager: insufficient vault liquidity"
        );

        uint256 loanId = loanReceipt.mintLoan(
            borrower,
            PRODUCT_ID,
            principal,
            risk.interestRateBps,
            terms.termDays,
            terms.collateralHash
        );

        loanDetails[loanId] = LoanDetails({
            purchasePrice: terms.purchasePrice,
            afterRepairValue: terms.afterRepairValue,
            rehabBudget: terms.rehabBudget,
            approvedBy: msg.sender,
            approvedAt: block.timestamp,
            fundedAt: block.timestamp,
            closedAt: 0
        });

        vault.lockForLoan(principal);
        axusd.safeTransferFrom(address(vault), borrower, principal);

        totalOriginated += principal;
        activeLoans++;

        emit LoanFunded(
            loanId,
            borrower,
            principal,
            terms.purchasePrice,
            terms.afterRepairValue
        );

        return loanId;
    }

    function pay(uint256 loanId, uint256 amount) external override nonReentrant whenNotPaused {
        require(amount > 0, "FixFlipManager: zero amount");

        ILoanReceipt.LoanData memory loan = loanReceipt.getLoan(loanId);
        require(loan.loanId == loanId, "FixFlipManager: loan not found");
        require(
            loan.status == ILoanReceipt.LoanStatus.Active ||
            loan.status == ILoanReceipt.LoanStatus.Repaying,
            "FixFlipManager: loan not payable"
        );

        uint256 totalDue = loanReceipt.calculateTotalDue(loanId);
        uint256 interestDue = loanReceipt.calculateInterestDue(loanId);
        uint256 principalRemaining = loan.principal - loan.amountRepaid;

        uint256 interestPortion;
        uint256 principalPortion;

        if (amount >= totalDue) {
            amount = totalDue;
            interestPortion = interestDue;
            principalPortion = amount - interestPortion;
        } else if (amount <= interestDue) {
            interestPortion = amount;
            principalPortion = 0;
        } else {
            interestPortion = interestDue;
            principalPortion = amount - interestPortion;
        }

        axusd.safeTransferFrom(msg.sender, address(repaymentRouter), amount);
        repaymentRouter.routePayment(loanId, amount, principalPortion, interestPortion);

        uint256 newAmountRepaid = loan.amountRepaid + principalPortion;
        totalRepaid += principalPortion;

        if (newAmountRepaid >= loan.principal) {
            loanReceipt.updateLoanStatus(loanId, ILoanReceipt.LoanStatus.Repaid);
            loanDetails[loanId].closedAt = block.timestamp;
            activeLoans--;
            emit LoanFullyRepaid(loanId, newAmountRepaid);
        } else {
            loanReceipt.updateLoanStatus(loanId, ILoanReceipt.LoanStatus.Repaying);
            emit LoanPaymentReceived(loanId, amount, loan.principal - newAmountRepaid);
        }
    }

    function closeLoan(uint256 loanId) external override onlyAdminAuthority {
        ILoanReceipt.LoanData memory loan = loanReceipt.getLoan(loanId);
        require(loan.loanId == loanId, "FixFlipManager: loan not found");
        require(
            loan.status == ILoanReceipt.LoanStatus.Repaid,
            "FixFlipManager: loan not fully repaid"
        );

        if (loanDetails[loanId].closedAt == 0) {
            loanDetails[loanId].closedAt = block.timestamp;
        }
    }

    function markDefaulted(uint256 loanId) external onlyAdminAuthority {
        ILoanReceipt.LoanData memory loan = loanReceipt.getLoan(loanId);
        require(loan.loanId == loanId, "FixFlipManager: loan not found");
        require(
            loan.status == ILoanReceipt.LoanStatus.Active ||
            loan.status == ILoanReceipt.LoanStatus.Repaying,
            "FixFlipManager: invalid status for default"
        );
        require(
            block.timestamp > loan.maturityTimestamp + 30 days,
            "FixFlipManager: grace period not elapsed"
        );

        loanReceipt.updateLoanStatus(loanId, ILoanReceipt.LoanStatus.Defaulted);
        loanDetails[loanId].closedAt = block.timestamp;
        activeLoans--;

        emit LoanDefaulted(loanId);
    }

    function getLoanDetails(uint256 loanId) external view returns (
        ILoanReceipt.LoanData memory loan,
        LoanDetails memory details
    ) {
        loan = loanReceipt.getLoan(loanId);
        details = loanDetails[loanId];
    }

    function getStats() external view returns (
        uint256 _totalOriginated,
        uint256 _totalRepaid,
        uint256 _activeLoans,
        uint256 _availableLiquidity
    ) {
        return (totalOriginated, totalRepaid, activeLoans, vault.availableLiquidity());
    }

    function activate() external onlyAdminAuthority whenNotGovernancePaused {
        active = true;
        emit ManagerActivated();
    }

    function deactivate() external onlyAdminAuthority {
        active = false;
        emit ManagerDeactivated();
    }

    function setVault(address _vault) external onlyAdminAuthority whenNotGovernancePaused {
        require(_vault != address(0), "FixFlipManager: invalid vault");
        vault = IPoolVault(_vault);
    }

    function setLoanReceipt(address _loanReceipt) external onlyAdminAuthority whenNotGovernancePaused {
        require(_loanReceipt != address(0), "FixFlipManager: invalid loanReceipt");
        loanReceipt = ILoanReceipt(_loanReceipt);
    }

    function setRiskConfig(address _riskConfig) external onlyAdminAuthority whenNotGovernancePaused {
        require(_riskConfig != address(0), "FixFlipManager: invalid riskConfig");
        riskConfig = IRiskConfig(_riskConfig);
    }

    function setRepaymentRouter(address _router) external onlyAdminAuthority whenNotGovernancePaused {
        require(_router != address(0), "FixFlipManager: invalid router");
        repaymentRouter = IRepaymentRouter(_router);
    }

    function pause() external onlyRole(GUARDIAN_ROLE) {
        _pause();
    }

    function unpause() external onlyAdminAuthority {
        _unpause();
    }
}

